export const lessons=Object.fromEntries(specs.map(([id,base,summary,scope])=>{const g=guides.find(x=>x.id===id);if(!g||!P[base])throw Error('Missing lesson '+id);let fields={...P[base],...overrides[id]};return [id,{...fields,id,base,summary,scope,preferences:prefs[base],cases:[{label:'현재 대표 수순의 구조',line:g.line,...fields,scope}],references:refs(base)}];}));
function refs(base){let i=base.includes('sicilian')||['dragon','maroczy'].includes(base)?0:base.startsWith('french')?1:base.startsWith('caro')?2:base==='quiet'?3:base==='berlin'?4:base==='qgd'||base==='carlsbad'?5:base==='nimzo'?6:base==='kid'?7:base==='grunfeld'?8:base==='benoni'?9:base==='slav'||base==='semi'?10:base==='fianchetto'?11:base==='scotch'?12:13;return [theorySources[i]];}
