add('vienna vienna-gambit','gambit-white','비엔나 · 수락 후 e5','e4 e5 Nc3 Nf6 f4 exf4 e5 Ng8 Nf3 d6 d4','백 e5–d4 공간과 흑 f4 여분 폰입니다. 백은 템포와 중앙을 얻지만 f열은 f4폰에 막힙니다.',{structure:'백 f폰과 흑 e폰이 교환되어 흑 f4폰이 남고 백 e5–d4 사슬이 공간을 얻습니다. 백은 폰 한 개의 비용과 전개 우위가, 흑은 f4 수비·중앙 반격이 중요합니다. …dxe5/…d5 가능성과 …Qh4+의 조건을 확인합니다.',pieces:['백: c3/f3 나이트가 중앙을 지원합니다. 비숍 전개·캐슬링으로 얻은 템포를 활동으로 바꿉니다. f열 룩은 흑 f4폰을 제거한 뒤 힘이 커집니다.','흑: g8 나이트는 후퇴해 다시 전개해야 합니다. 비숍·중앙 폰 반격으로 백 공간을 줄이며 킹 안전을 챙깁니다.']});
export function pawnFacts(c){const data={w:[],b:[]};for(const row of c.board())for(const x of row)if(x?.type==='p')data[x.color].push(x.square);const files=[...'abcdefgh'];const per=color=>{const own=data[color];const doubled=files.filter(f=>own.filter(s=>s[0]===f).length>1);const isolated=own.filter(s=>{const f=files.indexOf(s[0]);return !own.some(t=>Math.abs(files.indexOf(t[0])-f)===1)});return {pawns:own.sort(),doubled,isolated};};return {white:per('w'),black:per('b'),open:files.filter(f=>!data.w.concat(data.b).some(s=>s[0]===f)),semiWhite:files.filter(f=>!data.w.some(s=>s[0]===f)&&data.b.some(s=>s[0]===f)),semiBlack:files.filter(f=>!data.b.some(s=>s[0]===f)&&data.w.some(s=>s[0]===f))};}
export function moveReason(line,step){const seq=moves(line);if(!step)return null;const exact=annotations.find(a=>a.line.length===step&&a.line.every((v,i)=>v===seq[i]));if(exact)return exact;const before=position(seq.slice(0,step-1).join(' ')),m=before.move(seq[step-1]);const names={p:'폰',n:'나이트',b:'비숍',r:'룩',q:'퀸',k:'킹'};const after=before;let why=m.san.includes('O-O')?'킹을 안전한 곳으로 옮기고 룩을 연결합니다. 어느 파일을 쓸지는 폰 교환 이후 판단합니다.':m.captured?`${names[m.piece]}로 ${names[m.captured]}을 잡아 재료와 열린 선을 바꿉니다. 되잡기 후 폰 구조를 다시 확인합니다.`:m.piece==='p'?`${m.from}의 폰을 ${m.to}로 옮겨 공간과 통제 칸을 바꿉니다. 전진한 폰이 지키던 칸과 새로 약해진 칸도 확인합니다.`:`${names[m.piece]}를 ${m.from}에서 ${m.to}로 옮깁니다. 중앙 수비·공격 선·다음 돌파와 연결해 배치의 가치를 판단합니다.`;const opponent=m.color==='w'?'b':'w';const attacked=[];for(const row of after.board())for(const x of row)if(x?.color===opponent&&after.isAttacked(x.square,m.color))attacked.push(x.square);return {why,threat:after.isCheck()?'상대 킹이 체크를 받습니다. 체크 해소가 강제됩니다.':attacked.length?`현재 공격받는 상대 기물 칸: ${attacked.join(', ')}. 수비 여부에 따라 잡기가 성립하며, 이 수로 새로 만든 위협만을 뜻하지 않습니다.`:'체크나 공격받는 기물은 현재 보드에서 확인되지 않습니다. 폰 돌파와 배치 개선의 전략적 목적을 확인하세요.',ignore:after.isCheck()?'체크를 해결하지 않는 수는 둘 수 없습니다.':'직접 재료 위협의 성립은 상대 수비와 전술에 달립니다. 아래 대표 구조의 양쪽 계획으로 다음 대응을 판단하세요.'};}
extend(add,lessons);
export function familyLesson(g){if(lessons[g.id])return lessons[g.id];const seq=moves(g.line),name=(g.en||g.name||'').toLowerCase().replaceAll('’',"'");let choices=guides.filter(x=>name.startsWith(x.en.toLowerCase().replaceAll('’',"'").replace('grünfeld','grunfeld')));if(!choices.length){const ids=seq[0]==='e4'?(seq[1]==='c5'?['sicilian']:seq[1]==='e6'?['french']:seq[1]==='c6'?['caro']:seq[1]==='e5'?['open-game']:[]):seq[0]==='d4'?(seq[1]==='d5'?['closed-game']:seq[1]==='Nf6'?['indian']:[]):[];choices=guides.filter(x=>ids.includes(x.id));}return choices.sort((a,b)=>b.en.length-a.en.length).map(x=>lessons[x.id])[0]||null;}
